import '../styles/ShoppingList.css';
import Article from './Article';
import { itemList } from '../datas/itemList';
import { useState } from 'react';


function ShoppingList({ cart, updateCart }) {
  const sizeRange = ['M', 'L']

  return (
    <div className="shopping-list">
      <ul>
        {itemList.map((item) => (
          <li className='item' >
            {/* <Article {...item}/> */}
            <img className='item-cover' src={item.cover} alt={item.name} /><br />
            Name : {item.name}<br />
            {item.size && <span>Taille : {item.size}</span>}
            Comfort : {item.comfort}<br />
            Price : {item.price} €<br />
            {item.onSale && <span>En soldes !</span>}
            <button onClick={() => addToCart(item.name, item.price, cart, updateCart)}>Ajouter</button>
          </li>
        ))}
      </ul>
    </div>
  )
}

function addToCart(nameItem, priceItem, cart, updateCart) {
  const existingItem = cart.find((item) => item.name === nameItem);
  if (existingItem) {
    const updatedCart = cart.map((item) =>
      item.name === nameItem ? { ...item, quantity: item.quantity + 1 } : item
    );
    updateCart(updatedCart);
  } else {
    updateCart([...cart, { nameItem, priceItem, amount: 1}]);
  }
}


export default ShoppingList
